const i = $input.first().json;

const style = String(i.style ?? '').trim();
if (!style) throw new Error('wf-step-practice called with an empty style');

// nlq.common_practice returns at most ~30 rows at top_k 8, which is roughly 400
// tokens. The agent runs at num_ctx 16384 with `propose` already peaking near
// 7000, so this stays small on purpose -- top_k is clamped, not trusted.
const k = Number(i.top_k);
const top_k = Number.isFinite(k) ? Math.min(Math.max(Math.trunc(k), 3), 12) : 8;

return [{ json: { style, top_k, session_id: String(i.session_id ?? '') } }];

const src = $('Normalise input').first().json;

// Always Output Data is ON upstream, so "no matching style" arrives as one
// empty item rather than zero items. Filtering on `item` turns it back into
// the real answer: nothing.
const rows = $('Common practice').all().map(r => r.json).filter(r => r.item != null);

if (rows.length === 0) {
  return [{ json: { practice:
    `The recipe corpus has no usable sample for "${src.style}" — fewer than 30 matching ` +
    `recipes, so there is no common practice to report. Say so plainly; do not estimate one.` } }];
}

const bySection = new Map();
for (const r of rows) {
  if (!bySection.has(r.section)) bySection.set(r.section, []);
  bySection.get(r.section).push(r);
}

const overview = bySection.get('overview') ?? [];
const header = overview.find(r => r.item === 'recipes in corpus')?.typical ?? 'recipes';
const vitals = overview.filter(r => r.item !== 'recipes in corpus')
                       .map(r => `${r.item.replace('typical ', '')} ${r.typical}`)
                       .join(' · ');

const out = [];
// ⛔ The provenance line is not decoration. This is self-reported homebrew data
// with no publisher; an answer that presents it as guidance is the exact
// fabricated-authority failure the closed-book design exists to prevent. The
// model is told what this is on every single call.
out.push(`WHAT BREWERS ACTUALLY DO — "${src.style}"`);
out.push(`Source: ${header} self-reported by homebrewers on a public recipe site.`);
out.push(`This is OBSERVED PRACTICE, not published guidance. Attribute it as "what brewers`);
out.push(`commonly do" — never as what a book, the BJCP or a style guideline says.`);
if (vitals) out.push(`\nTypical outcome: ${vitals}`);

const titles = {
  'grain bill': 'GRAIN BILL',
  'hops': 'HOPS',
  'yeast': 'YEAST',
  'other additions': 'WATER SALTS, FININGS AND OTHER ADDITIONS',
};
for (const [key, title] of Object.entries(titles)) {
  const rs = bySection.get(key);
  if (!rs || rs.length === 0) continue;
  out.push(`\n${title}  (share of recipes · typical amount)`);
  for (const r of rs) {
    const pct = r.pct_of_recipes == null ? '' : `${r.pct_of_recipes}% of recipes`;
    out.push(`  ${r.item} — ${pct}, ${r.typical}`);
  }
}

return [{ json: { practice: out.join('\n'), style: src.style, rows: rows.length } }];
